INSERT INTO "BearerAct" ("id", "name", "createdAt", "updatedAt")
VALUES
  ('c1121e0a-34de-4de4-97dc-77544d641761', 'Constitutional and Political', '2026-09-23T13:05:37.659Z', '2026-09-23T13:05:37.659Z'),
