INSERT INTO "Review" ("id", "userId", "advocateId", "rating", "reviewText", "createdAt", "updatedAt")
VALUES
  ('5b7e9960-7db2-47e5-a0c1-0f91c70cfefd', '2602153c-150e-467b-961b-c7777a0f8e6d', 'e72845c5-3d35-492d-a97c-1e83d80b3670', 4, 'Highly professional and punctual. Resolved my issue efficiently.', '2026-09-29T06:45:46.405Z', '2026-09-29T06:45:46.405Z'),
  ('62ecb6fa-dfb6-494f-b348-770ed8c2d965', 'ad2a07a5-ec7e-417d-8985-e523614f419f', '0eafa305-e70d-42f7-82b9-baa2a5e6bc72', 4, 'Superb experience. Detail-oriented planning and solid defense/representation.', '2026-09-29T06:45:46.762Z', '2026-09-29T06:45:46.762Z'),
  ('da030362-ce5b-4124-b33f-be4c15fd403f', '1c546ec3-1d0a-4509-8c07-76d832dca59d', '0eafa305-e70d-42f7-82b9-baa2a5e6bc72', 5, 'Helpful, but a bit hard to reach over phone. Good legal knowledge though.', '2026-09-29T06:45:47.200Z', '2026-09-29T06:45:47.200Z'),
  ('3d82647a-17bf-4f37-a7c0-fe14827b020a', '4cfc9d02-0411-42ea-aff9-5c57f17ed002', '0eafa305-e70d-42f7-82b9-baa2a5e6bc72', 5, 'Superb experience. Detail-oriented planning and solid defense/representation.', '2026-09-29T06:45:47.627Z', '2026-09-29T06:45:47.627Z'),
  ('0c80ee8e-0c59-45a2-9893-26779bf94df9', 'ad2a07a5-ec7e-417d-8985-e523614f419f', 'ce08bf5e-aaf9-4a17-a6a8-3696b2908a80', 5, 'Advocate Rajesh is extremely knowledgeable and professional. He handled our family bail application with utmost diligence and secured the bail in record time. Highly recommended!', '2026-09-29T06:45:17.697Z', '2026-09-29T06:45:17.697Z'),
  ('1d271fbb-c8ac-4a21-811c-87bd08c15e27', '1c546ec3-1d0a-4509-8c07-76d832dca59d', 'ce08bf5e-aaf9-4a17-a6a8-3696b2908a80', 4, 'Very experienced lawyer. Answered all my criminal litigation queries clearly. The fees are high but worth the professional expertise.', '2026-09-29T06:45:18.290Z', '2026-09-29T06:45:18.290Z'),
  ('31589650-07ab-4f11-9689-a20a79581b05', 'cc9ef2c1-0851-407b-9b6b-fcf29b8b6486', 'ce08bf5e-aaf9-4a17-a6a8-3696b2908a80', 4, 'Knowledgeable and helpful.', '2026-09-29T06:45:18.571Z', '2026-09-29T06:45:18.571Z'),
  ('b8de92cd-d8e7-401c-bf0c-3df34ca7ebb9', 'ad2a07a5-ec7e-417d-8985-e523614f419f', '442f6fa6-d27a-40a7-9d85-7c03dc69c1f8', 5, 'Excellent corporate legal consultant. She reviewed our term sheets and shareholder agreements thoroughly. Great for tech startups.', '2026-09-29T06:45:18.976Z', '2026-09-29T06:45:18.976Z'),
  ('5fd5d328-3d49-4c8a-b3ff-52f089087356', '1c546ec3-1d0a-4509-8c07-76d832dca59d', '442f6fa6-d27a-40a7-9d85-7c03dc69c1f8', 5, 'Priya helped us register our trademark and patent files. Her advice was prompt and clear.', '2026-09-29T06:45:19.284Z', '2026-09-29T06:45:19.284Z'),
  ('cdd3ba67-0a41-4fad-9dec-297366c76b83', 'cc9ef2c1-0851-407b-9b6b-fcf29b8b6486', '442f6fa6-d27a-40a7-9d85-7c03dc69c1f8', 4, 'Detailed contract review.', '2026-09-29T06:45:19.563Z', '2026-09-29T06:45:19.563Z'),
  ('f0017592-6390-4678-bf4a-132497293a09', 'c4fe0376-0462-46e0-8646-e32c6a4a5bc7', '442f6fa6-d27a-40a7-9d85-7c03dc69c1f8', 4, 'Very professional interaction.', '2026-09-29T06:45:19.843Z', '2026-09-29T06:45:19.843Z'),
  ('bf275261-459c-4fc8-bf97-e26543eff878', 'ad2a07a5-ec7e-417d-8985-e523614f419f', '30960335-58ed-4374-9abd-f096061b8825', 4, 'Amit helped resolving a property dispute with our tenant. Good knowledge of local RERA rules.', '2026-09-29T06:45:20.129Z', '2026-09-29T06:45:20.129Z'),
  ('18eac7e2-5f17-4121-b4bf-99b5d37bfa16', '1c546ec3-1d0a-4509-8c07-76d832dca59d', '30960335-58ed-4374-9abd-f096061b8825', 4, 'Good legal consultation.', '2026-09-29T06:45:20.412Z', '2026-09-29T06:45:20.412Z'),
  ('7f21946f-f0eb-4d34-85f0-4be38ebf1703', 'cc9ef2c1-0851-407b-9b6b-fcf29b8b6486', '30960335-58ed-4374-9abd-f096061b8825', 4, 'Helped resolve our real estate issues.', '2026-09-29T06:45:20.704Z', '2026-09-29T06:45:20.704Z'),
  ('c19c72a7-11d1-49c7-aacb-7143d4a84bf4', 'ad2a07a5-ec7e-417d-8985-e523614f419f', '6aaa8576-2d08-48ee-a95c-52b85bd6b996', 5, 'Sneha was incredibly compassionate and logical during a stressful child custody dispute. Excellent family court advocacy.', '2026-09-29T06:45:20.987Z', '2026-09-29T06:45:20.987Z'),
  ('306b410c-a895-4419-85c3-f847f5dab41c', '1c546ec3-1d0a-4509-8c07-76d832dca59d', '6aaa8576-2d08-48ee-a95c-52b85bd6b996', 4, 'Highly supportive lawyer. Handled my mutual divorce proceedings smoothly.', '2026-09-29T06:45:21.343Z', '2026-09-29T06:45:21.343Z'),
  ('000a8c0d-c8ef-48e3-8ede-99b337787ea1', 'cc9ef2c1-0851-407b-9b6b-fcf29b8b6486', '6aaa8576-2d08-48ee-a95c-52b85bd6b996', 5, 'Very compassionate and professional.', '2026-09-29T06:45:21.638Z', '2026-09-29T06:45:21.638Z'),
  ('58aabb87-40e2-4cc1-8626-1ce5c6c2470b', 'ad2a07a5-ec7e-417d-8985-e523614f419f', 'c9160d17-02ef-43ac-8773-1044afc2cbaf', 5, 'Superb taxation advice. Solved a complicated corporate tax audit problem easily.', '2026-09-29T06:45:21.918Z', '2026-09-29T06:45:21.918Z'),
